BEGIN;
CREATE TABLE member_feature_flags (key TEXT PRIMARY KEY CHECK (key IN ('qa','artwork','challenges','gallery','certificates')), enabled BOOLEAN NOT NULL DEFAULT false, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO member_feature_flags(key) VALUES ('qa'),('artwork'),('challenges'),('gallery'),('certificates');
CREATE TABLE member_plans (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 100), duration_days INTEGER NOT NULL CHECK(duration_days BETWEEN 1 AND 730), price INTEGER NOT NULL CHECK(price > 0), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO member_plans(name,duration_days,price,status) VALUES ('30 hari',30,30000,'active');
ALTER TABLE member_orders ADD COLUMN plan_id BIGINT REFERENCES member_plans(id);
ALTER TABLE member_orders ADD COLUMN plan_name TEXT;
UPDATE member_orders SET plan_name='30 hari' WHERE plan_name IS NULL;
CREATE TABLE member_vouchers (id BIGSERIAL PRIMARY KEY, code_hash TEXT NOT NULL UNIQUE, label TEXT NOT NULL CHECK(length(label) BETWEEN 2 AND 100), days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 730), max_uses INTEGER NOT NULL CHECK(max_uses BETWEEN 1 AND 100000), uses INTEGER NOT NULL DEFAULT 0 CHECK(uses>=0 AND uses<=max_uses), expires_at TIMESTAMPTZ, archived_at TIMESTAMPTZ, reason TEXT NOT NULL CHECK(length(reason) BETWEEN 2 AND 500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE member_voucher_redemptions (voucher_id BIGINT REFERENCES member_vouchers(id), member_id BIGINT REFERENCES member_accounts(id), redeemed_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(voucher_id,member_id));
ALTER TABLE member_courses ADD COLUMN release_at TIMESTAMPTZ;
ALTER TABLE member_lessons ADD COLUMN release_at TIMESTAMPTZ;
CREATE TABLE member_questions (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES member_accounts(id) ON DELETE CASCADE, course_id BIGINT NOT NULL REFERENCES member_courses(id) ON DELETE CASCADE, question TEXT NOT NULL CHECK(length(question) BETWEEN 1 AND 1000), answer TEXT CHECK(length(answer)<=2000), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','answered','closed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), answered_at TIMESTAMPTZ);
CREATE INDEX member_questions_quota ON member_questions(member_id,course_id,created_at);
CREATE TABLE member_challenges (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL CHECK(length(title) BETWEEN 2 AND 200), prompt TEXT NOT NULL CHECK(length(prompt) BETWEEN 2 AND 3000), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), opens_at TIMESTAMPTZ NOT NULL, closes_at TIMESTAMPTZ NOT NULL, CHECK(closes_at>opens_at));
CREATE TABLE member_artworks (id BIGSERIAL PRIMARY KEY, member_id BIGINT NOT NULL REFERENCES member_accounts(id) ON DELETE CASCADE, course_id BIGINT REFERENCES member_courses(id), challenge_id BIGINT REFERENCES member_challenges(id), title TEXT NOT NULL DEFAULT 'Karya Member Nala' CHECK(length(title) BETWEEN 1 AND 100), storage_name TEXT NOT NULL UNIQUE, feedback TEXT CHECK(length(feedback)<=1500), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(course_id IS NOT NULL OR challenge_id IS NOT NULL));
CREATE UNIQUE INDEX member_artwork_challenge_once ON member_artworks(member_id,challenge_id) WHERE challenge_id IS NOT NULL;
CREATE INDEX member_artworks_quota ON member_artworks(member_id,created_at);
CREATE TABLE member_gallery_consents (artwork_id BIGINT PRIMARY KEY REFERENCES member_artworks(id) ON DELETE CASCADE, member_id BIGINT NOT NULL REFERENCES member_accounts(id) ON DELETE CASCADE, caption TEXT NOT NULL CHECK(length(caption) BETWEEN 1 AND 100), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')), consented_at TIMESTAMPTZ NOT NULL DEFAULT now(), moderated_at TIMESTAMPTZ);
CREATE TABLE member_certificate_rules (course_id BIGINT PRIMARY KEY REFERENCES member_courses(id) ON DELETE CASCADE, enabled BOOLEAN NOT NULL DEFAULT false, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE member_certificates (id BIGSERIAL PRIMARY KEY, certificate_id UUID NOT NULL UNIQUE, member_id BIGINT NOT NULL REFERENCES member_accounts(id), course_id BIGINT NOT NULL REFERENCES member_courses(id), course_title TEXT NOT NULL, display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 2 AND 100), issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ, UNIQUE(member_id,course_id));
COMMIT;
